{"source":"def investigate(context, acquire):
    actions = context.get('actions', [])
    committed = set()
    pending = None
    high = 0
    for action in actions:
        op = action.get('op')
        if op == 'begin':
            pending = set(committed)
        elif op == 'commit':
            committed = pending
            pending = None
        elif op == 'rollback':
            pending = None
        elif op == 'put':
            row_id = action.get('id')
            if pending is None:
                committed.add(row_id)
            else:
                pending.add(row_id)
            if row_id > high:
                high = row_id
        elif op == 'delete':
            row_id = action.get('id')
            if pending is None:
                committed.discard(row_id)
            else:
                pending.discard(row_id)
    return high + 1
